import React from "react";
import { motion } from "framer-motion";

const ExperienceBadges = ({ theme = "dark" }) => {
  const badges = [
    { 
      text: "1.5+ Years Full Stack Dev",
      emoji: "🧑‍💻",
      color: "from-blue-500 to-blue-600",
      darkColor: "from-blue-400 to-blue-500"
    },
    { 
      text: "Built 10+ Web Apps",
      emoji: "🌐",
      color: "from-purple-500 to-purple-600",
      darkColor: "from-purple-400 to-purple-500"
    },
    { 
      text: "MERN Stack Specialist",
      emoji: "🚀",
      color: "from-green-500 to-green-600",
      darkColor: "from-green-400 to-green-500"
    },
    { 
      text: "Clean & Scalable Code",
      emoji: "🛠️",
      color: "from-amber-500 to-amber-600",
      darkColor: "from-amber-400 to-amber-500"
    },
    { 
      text: "Focused on UI/UX & Performance",
      emoji: "📈",
      color: "from-rose-500 to-rose-600",
      darkColor: "from-rose-400 to-rose-500"
    },
    { 
      text: "Continuous Learner",
      emoji: "📚",
      color: "from-indigo-500 to-indigo-600",
      darkColor: "from-indigo-400 to-indigo-500"
    },
  ];

  const container = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1
      }
    }
  };

  const item = {
    hidden: { y: 20, opacity: 0 },
    visible: {
      y: 0,
      opacity: 1,
      transition: {
        duration: 0.5,
        ease: "easeOut"
      }
    }
  };

  return (
    <section className={`py-12 sm:py-16 lg:py-20 ${theme === 'dark' ? 'bg-gray-900' : 'bg-gray-50'}`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="text-center mb-10 sm:mb-12 lg:mb-16"
        >
          <h2 className={`text-2xl sm:text-3xl lg:text-4xl font-bold mb-3 sm:mb-4 ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
            <span className="inline-block mr-2">🏅</span>
            Experience Highlights
          </h2>
          <div className={`w-16 sm:w-20 h-1 mx-auto mb-4 sm:mb-6 ${theme === 'dark' ? 'bg-indigo-500' : 'bg-indigo-600'}`}></div>
          <p className={`text-base sm:text-lg max-w-2xl mx-auto ${theme === 'dark' ? 'text-gray-300' : 'text-gray-600'}`}>
            Key achievements and specialties that define my expertise
          </p>
        </motion.div>

        <motion.div
          variants={container}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: "-50px" }}
          className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5 sm:gap-6 lg:gap-8"
        >
          {badges.map((badge, index) => (
            <motion.div
              key={index}
              variants={item}
              whileHover={{ y: -5, scale: 1.03 }}
              className={`p-1 rounded-xl bg-gradient-to-r ${theme === 'dark' ? badge.darkColor : badge.color} shadow-lg`}
            >
              <div className={`flex items-center justify-center p-4 sm:p-5 rounded-lg ${theme === 'dark' ? 'bg-gray-800' : 'bg-white'} h-full`}>
                <span className="text-2xl sm:text-3xl mr-3">{badge.emoji}</span>
                <h3 className={`text-sm sm:text-base font-medium ${theme === 'dark' ? 'text-gray-100' : 'text-gray-800'}`}>
                  {badge.text}
                </h3>
              </div>
            </motion.div>
          ))}
        </motion.div>

        {/* Additional Stats Section */}
        <motion.div
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          transition={{ delay: 0.4 }}
          className="mt-12 sm:mt-16 grid grid-cols-2 md:grid-cols-4 gap-4 sm:gap-6"
        >
          <div className={`p-4 sm:p-5 rounded-xl text-center ${theme === 'dark' ? 'bg-gray-800' : 'bg-white'} shadow-md`}>
            <div className={`text-2xl sm:text-3xl font-bold mb-2 ${theme === 'dark' ? 'text-blue-400' : 'text-blue-600'}`}>10+</div>
            <p className={`text-sm ${theme === 'dark' ? 'text-gray-300' : 'text-gray-600'}`}>Projects Completed</p>
          </div>
          <div className={`p-4 sm:p-5 rounded-xl text-center ${theme === 'dark' ? 'bg-gray-800' : 'bg-white'} shadow-md`}>
            <div className={`text-2xl sm:text-3xl font-bold mb-2 ${theme === 'dark' ? 'text-purple-400' : 'text-purple-600'}`}>5+</div>
            <p className={`text-sm ${theme === 'dark' ? 'text-gray-300' : 'text-gray-600'}`}>Happy Clients</p>
          </div>
          <div className={`p-4 sm:p-5 rounded-xl text-center ${theme === 'dark' ? 'bg-gray-800' : 'bg-white'} shadow-md`}>
            <div className={`text-2xl sm:text-3xl font-bold mb-2 ${theme === 'dark' ? 'text-green-400' : 'text-green-600'}`}>1.5+</div>
            <p className={`text-sm ${theme === 'dark' ? 'text-gray-300' : 'text-gray-600'}`}>Years Experience</p>
          </div>
          <div className={`p-4 sm:p-5 rounded-xl text-center ${theme === 'dark' ? 'bg-gray-800' : 'bg-white'} shadow-md`}>
            <div className={`text-2xl sm:text-3xl font-bold mb-2 ${theme === 'dark' ? 'text-amber-400' : 'text-amber-600'}`}>100%</div>
            <p className={`text-sm ${theme === 'dark' ? 'text-gray-300' : 'text-gray-600'}`}>Commitment</p>
          </div>
        </motion.div>
      </div>
    </section>
  );
};

export default ExperienceBadges;