import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

const SkillWithTooltip = ({ name, description }) => {
  const [isHovered, setIsHovered] = useState(false);
  const [position, setPosition] = useState({ x: 0, y: 0 });

  const getIcon = () => {
    const colors = [
      'bg-blue-100 text-blue-600',
      'bg-purple-100 text-purple-600',
      'bg-green-100 text-green-600',
      'bg-yellow-100 text-yellow-600',
      'bg-red-100 text-red-600',
      'bg-indigo-100 text-indigo-600'
    ];
    const randomColor = colors[Math.floor(Math.random() * colors.length)];

    return (
      <div className={`w-12 h-12 rounded-xl flex items-center justify-center ${randomColor}`}>
        <span className="text-xl font-bold">{name.charAt(0).toUpperCase()}</span>
      </div>
    );
  };

  const handleMouseMove = (e) => {
    const tooltipOffset = 20;
    const tooltipWidth = 220;

    let x = e.clientX + tooltipOffset;
    let y = e.clientY + tooltipOffset;

    if (x + tooltipWidth > window.innerWidth) {
      x = window.innerWidth - tooltipWidth - 20;
    }

    setPosition({ x, y });
  };

  return (
    <div
      className="relative inline-block m-2 group"
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      onMouseMove={handleMouseMove}
    >
      <motion.div
        className="p-1 bg-white dark:bg-gray-800 rounded-xl shadow-sm hover:shadow-md transition-all duration-300 cursor-default border border-gray-100 dark:border-gray-700"
        whileHover={{ scale: 1.05 }}
      >
        {getIcon()}
      </motion.div>

      <AnimatePresence>
        {isHovered && (
          <motion.div
            className="fixed z-50 p-3 bg-gradient-to-br from-gray-800 to-gray-900 text-white text-sm rounded-lg shadow-2xl pointer-events-none min-w-[200px] max-w-xs backdrop-blur-sm bg-opacity-90"
            style={{
              left: `${position.x}px`,
              top: `${position.y}px`,
            }}
            initial={{ opacity: 0, y: 15, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 15, scale: 0.95 }}
            transition={{
              type: 'spring',
              damping: 20,
              stiffness: 300,
              mass: 0.5
            }}
          >
            <div className="flex items-start">
              <div className="mr-2 mt-0.5">{getIcon()}</div>
              <div>
                <div className="font-semibold text-white">{name}</div>
                <div className="text-gray-300 text-xs mt-1 leading-relaxed">{description}</div>
              </div>
            </div>
            <div className="absolute -top-1.5 left-3 w-3 h-3 bg-gray-800 transform rotate-45 z-0"></div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

const PremiumSkillsSection = () => {
  const skills = [
    { name: "Tailwind CSS", description: "Utility-first CSS framework for rapid UI development with responsive design" },
    { name: "React", description: "Declarative JavaScript library for building modern user interfaces" },
    { name: "Node.js", description: "JavaScript runtime for building scalable server-side applications" },
    { name: "Figma", description: "Collaborative interface design tool with powerful prototyping features" },
    { name: "MongoDB", description: "NoSQL database program using document-oriented data model" },
    { name: "GraphQL", description: "Query language for APIs that provides complete description of data" },
    { name: "TypeScript", description: "Strongly typed programming language that builds on JavaScript" },
    { name: "Docker", description: "Platform for developing, shipping, and running applications in containers" }
  ];

  return (
    <div className="max-w-6xl mx-auto px-4 sm:px-6 py-12">
      <div className="text-center mb-12">
        <h2 className="text-3xl font-bold text-gray-800 dark:text-white mb-3">Technical Expertise</h2>
        <p className="text-gray-600 dark:text-gray-300 max-w-2xl mx-auto text-base sm:text-lg">
          Technologies I'm proficient with and use regularly in my projects
        </p>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4 justify-items-center">
        {skills.map((skill, index) => (
          <SkillWithTooltip
            key={index}
            name={skill.name}
            description={skill.description}
          />
        ))}
      </div>
    </div>
  );
};

export default PremiumSkillsSection;
